CREATE TABLE `ws_sale_order` (
  `sale_order_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '销售单id',
  `sale_order_code` varchar(100) DEFAULT NULL COMMENT '销售单编号',
  `customer_id` bigint(20) DEFAULT NULL COMMENT '客户id',
  `invoice_customer_id` bigint(20) DEFAULT NULL COMMENT '开票客户id',
  `channel_id` bigint(20) DEFAULT NULL COMMENT '渠道id(字典表id)',
  `goods_id` bigint(20) DEFAULT NULL COMMENT '物料型号id',
  `bid_price` decimal(10,2) DEFAULT '0.00' COMMENT '物料标价',
  `sell_price` decimal(14,6) DEFAULT '0.000000' COMMENT '售价',
  `sale_num` decimal(10,3) DEFAULT '0.000' COMMENT '销售数量',
  `sale_order_price` decimal(20,6) DEFAULT '0.000000' COMMENT '订单金额（售价*数量）',
  `payment_type` int(5) DEFAULT NULL COMMENT '收款方式id（欠款；现款）',
  `reimbursement_date` date DEFAULT NULL COMMENT '报账日期',
  `residue_credit_amount` decimal(20,6) DEFAULT NULL COMMENT '剩余信用额度',
  `order_state` int(5) DEFAULT NULL COMMENT '订单状态（待审核；已生效；已取消；已驳回；已报账；已红冲；待收款）',
  `invoice_state` int(5) DEFAULT '0' COMMENT '开票状态 0-未开票 1-已开票',
  `is_split` int(5) DEFAULT '0' COMMENT '是否拆分状态 0-业务提交 1-由拆分产生',
  `income_state` int(5) DEFAULT '0' COMMENT '收款状态（0-待收款、1-已收款）',
  `sale_day_review_id` bigint(20) DEFAULT NULL COMMENT '销售单_日审id',
  `create_user_id` bigint(20) DEFAULT NULL COMMENT '创建人id',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) DEFAULT NULL COMMENT '更新人id',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `plan_code` varchar(50) DEFAULT NULL COMMENT '计划单编号',
  `red_rush_order_code` varchar(50) DEFAULT NULL COMMENT '红冲单号',
  `sale_type` int(5) DEFAULT NULL COMMENT '0-批发销售，1-零售销售',
  `submit_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `bind_state` int(11) DEFAULT '150' COMMENT '绑定状态',
  `income_amount` decimal(20,2) DEFAULT '0.00' COMMENT '销售单关联金额',
  `lock_price` int(2) NOT NULL DEFAULT '0' COMMENT '定金锁价-默认否 0,是 1',
  `lock_price_order_code` varchar(20) DEFAULT NULL COMMENT '关联的定金锁价计划单编号',
  PRIMARY KEY (`sale_order_id`),
  UNIQUE KEY `unique_salecode` (`sale_order_code`),
  KEY `idx_cid` (`customer_id`) USING BTREE,
  KEY `idx_icid` (`invoice_customer_id`) USING BTREE,
  KEY `idx_gid` (`goods_id`) USING BTREE,
  KEY `idx_sdrid` (`sale_day_review_id`) USING BTREE,
  KEY `idx_rd` (`reimbursement_date`) USING BTREE,
  KEY `idx_lpdc` (`lock_price_order_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=25414 DEFAULT CHARSET=utf8mb4 COMMENT='批发零售销售订单表';
